assign out = ^in; // Built-in XOR operator for parity

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);

assign out = ~(^in[1] ^ ~(^in[3] ^ in[2]) ^ ^in[5] ^ ~(^in[4] ^ in[7]) ^ ~(^in[6] ^ in[0]));

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);
    wire select1, select2, select3, select4;

    assign select1 = in[1];
    assign select2 = in[3];
    assign select3 = in[5];
    assign select4 = in[7];

    assign in[0] ? ~({1'b0, select1} | {1'b1, select2}) :
          select1 ? ~({1'b0, select1} | {1'b1, select2}) :
          in[0] ? ~({1'b0, select1} | {1'b1, select2}) :
          ~in[0];

    assign in[2] ? ~({1'b0, select3} | {1'b1, select4}) :
          select3 ? ~({1'b0, select3} | {1'b1, select4}) :
          in[2] ? ~({1'b0, select3} | {1'b1, select4}) :
          ~in[2];

    assign out = select1 ? select3 : select2 ? select4 : in[1] ? in[5] : 
          select3 ? select2 : in[3] ? in[7] : in[1] ? select3 : in[5];

endmodule

module parity_8bit (
    input [7:0] in,
    output out
);

    wire w1, w2, w3, w4, w5, w6;

    assign w1 = in[1] ^ in[0];
    assign w2 = ~(in[3] ^ in[2]);
    assign w3 = in[5] ^ in[4];
    assign w4 = ~(in[7] ^ in[6]);

    assign w5 = w1 ^ w2;
    assign w6 = w3 ^ w4;

    assign out = w5 ^ w6 ^ in[0];

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire n_sel0 = ~sel[0];
    wire n_sel1 = ~sel[1];
    wire n_in0 = ~in[0];
    wire n_in1 = ~in[1];
    wire n_in2 = ~in[2];
    wire n_in3 = ~in[3];
    wire t_in0 = in[0] & n_sel0;
    wire t_in1 = in[1] & n_sel1;
    wire t_sel = sel[1] & sel[0];
    wire t0 = in[0] & n_sel0 & n_sel1;
    wire t1 = in[1] & n_sel0 & sel[1];
    wire t2 = in[2] & sel[0] & n_sel1;
    wire t3 = in[3] & sel[0] & sel[1];
    wire t4 = in[0] & sel[1] & n_sel0;
    wire t5 = in[1] & sel[1] & n_sel0;
    wire t6 = in[2] & n_sel1 & n_sel0;
    wire t7 = in[3] & n_sel1 & n_sel0;
    wire t8 = in[0] & sel[1] & sel[0];
    wire t9 = in[1] & sel[0] & sel[1];
    wire t10 = in[2] & sel[0] & n_sel1;
    wire t11 = in[3] & sel[0] & n_sel1;
    wire t12 = sel[0] & n_sel1 & n_sel0;
    wire t13 = sel[1] & n_sel0 & n_sel0;
    wire t14 = sel[0] & sel[1] & n_sel1;
    wire t15 = sel[0] & n_sel0 & sel[1];

    assign out = t0 | t1 | t2 | t3 | t4 | t5 | t6 | t7 | t8 | t9 | t10 | t11 | t12 | t13 | t14 | t15;
endmodule

module mux4to1 (
