                  ((sel[0] in[sel[1]] ~~in[sel[1]]) | (sel[0] in[sel[1]] ~~in[sel[1]])) | 
                  ((sel[0] in[sel[1]] ~~in[sel[1]]) | (sel[0] in[sel[1]] ~~in[sel[1]])) & in[sel[1]];

