module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire nsel0, nsel1, nsel2, nsel3;
    wire n_in0, n_in1, n_in2, n_in3;
    wire temp1, temp2, temp3, temp4, temp5, temp6, temp7;

    assign nsel0 = ~sel[0];
    assign nsel1 = sel[0];
    assign nsel2 = ~sel[1];
    assign nsel3 = sel[1];

    assign n_in0 = ~in[0];
    assign n_in1 = ~in[1];
    assign n_in2 = ~in[2];
    assign n_in3 = ~in[3];

    assign temp1 = nsel0 & n_in0;
    assign temp2 = nsel1 & n_in1;
    assign temp3 = nsel2 & n_in2;
    assign temp4 = nsel3 & n_in3;

    assign temp5 = temp1 | temp2;
    assign temp6 = temp3 | temp4;

    assign temp7 = temp5 & ~temp6;

    assign out = temp7;

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire w1, w2, w3, w4, w5, w6, w7, w8;

    assign w1 = (~in[0]) & in[1];
    assign w2 = (~in[1]) & in[0];
    assign w3 = (~sel[0]) & (~sel[1]);
    assign w4 = ~in[2];
    assign w5 = in[2];
    assign w6 = (~sel[1]) & sel[0];
    assign w7 = in[3];
    assign w8 = in[3];

    assign out = ~(~w1 & w2 & w3 & w4 & w5 & w6 & w7 & w8);

endmodule

