module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    wire a0, a1, a2, a3;
    wire b0, b1, b2, b3;
    assign a0 = a[0];
    assign a1 = a[1];
    assign a2 = a[2];
    assign a3 = a[3];
    assign b0 = b[0];
    assign b1 = b[1];
    assign b2 = b[2];
    assign b3 = b[3];

    wire nand1_out;
    wire nor2_out;
    wire nand3_out;
    wire nand4_out;
    wire nor3_out;
    wire nor4_out;
    wire nor5_out;
    wire and1_out;
    wire and2_out;
    wire nor6_out;

    assign n1 = ~(a0 | b0);
    assign n2 = ~(a1 | b1);
    assign n3 = ~(a2 | b2);
    assign n4 = ~(a3 | b3);

    assign nand1_out = ~(n1 & n2);
    assign nor2_out = ~(a1 & b1);
    assign and1_out = (nor2_out & n3);
    assign nor3_out = ~(a2 & b2);
    assign nor4_out = ~(a3 & b3);
    assign and2_out = (nor4_out & nor3_out);
    assign nor5_out = ~(a3 & b3);
    assign nand3_out = ~(nor5_out & and2_out);
    assign nor6_out = ~(a2 & b2);
    assign nand4_out = ~(nand3_out & nor6_out);
    assign equal = nand4_out;

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire a_sel0, a_sel1, a_sel2, a_sel3;
    wire b_sel0, b_sel1, b_sel2, b_sel3;

    assign a_sel0 = a[0];
    assign a_sel1 = a[1];
    assign a_sel2 = a[2];
    assign a_sel3 = a[3];

    assign b_sel0 = b[0];
    assign b_sel1 = b[1];
    assign b_sel2 = b[2];
    assign b_sel3 = b[3];

    wire and_out1;
    wire and_out2;
    wire and_out3;
    wire or_out1;
    wire or_out2;

    assign and_out1 = ~(~a_sel0 | ~b_sel0);
    assign and_out2 = ~(a_sel1 | b_sel1);
    assign and_out3 = ~and_out1;

    assign or_out1 = and_out1 & or_out2;
    assign or_out2 = and_out2 & ~a_sel2 & ~b_sel2;

    assign equal = ~(or_out1 | ~(and_out3 | or_out2));

endmodule

