);

    wire [3:0] b_val;
    wire [3:0] a_val;
    wire out1;
    wire out2;
    wire out3;
    wire out4;
    wire out5;
    wire out6;

    assign b_val = b;
    assign a_val = a;

    assign out1 = ~(b_val[0] | b_val[1] | b_val[2] | b_val[3]);
    assign out2 = (b_val[0] & b_val[1]) | (b_val[0] & b_val[2]) | (b_val[0] & b_val[3]) |
                  (b_val[1] & b_val[2]) | (b_val[1] & b_val[3]) | (b_val[2] & b_val[3]);
    assign out3 = ~(a_val[0] | a_val[1] | a_val[2] | a_val[3]);
    assign out4 = (a_val[0] & a_val[1]) | (a_val[0] & a_val[2]) | (a_val[0] & a_val[3]) |
                  (a_val[1] & a_val[2]) | (a_val[1] & a_val[3]) | (a_val[2] & a_val[3]);
    assign out5 = a_val[0] | a_val[1];
    assign out6 = a_val[1] | a_val[2];

    assign out4 = out4 | out5;
    assign out4 = out4 | out6;

    assign out1 = out1 & b_val[0];
    assign out2 = out2 & b_val[1];
    assign out3 = out3 & b_val[2];
    assign out4 = out4 & b_val[3];

    assign equal = ~out1 | ~out2 | ~out3 | ~out4;

endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire [3:0] a_sel;
    wire [3:0] b_sel;
    wire a_eq_b;
    wire a_gt_b;
    wire a_lt_b;
    wire b_gt_a;
    wire b_lt_a;
    wire a_ge_b;
    wire a_le_b;
    wire b_ge_a;
    wire b_le_a;
    wire not_equal;
    wire not_eq_and_not_lt;
    wire not_eq_and_not_gt;
    wire final_equ;

    assign a_sel = a;
    assign b_sel = b;

    assign a_ge_b = (a[3] & b[3]) | ((a[3] & ~b[3]) & ({3{a[2:0]}} >= {3{b[2:0]}}));
    assign a_le_b = (~a[3] & ~b[3]) | ((~a[3] & b[3]) & ({3{a[2:0]}} <= {3{b[2:0]}}));
    assign b_ge_a = (b[3] & a[3]) | ((b[3] & ~a[3]) & ({3{b[2:0]}} >= {3{a[2:0]}}));
    assign b_le_a = (~b[3] & ~a[3]) | ((~b[3] & a[3]) & ({3{b[2:0]}} <= {3{a[2:0]}}));

    assign a_lt_b = (not a_ge_b && not a_eq_b && not a_gt_b);
    assign a_gt_b = (not a_le_b && not a_eq_b && not a_lt_b);
    assign b_lt_a = (not b_ge_a && not b_eq_a && not b_gt_a);
    assign b_gt_a = (not b_le_a && not b_eq_a && not b_lt_a);

    assign not_equal = ~(a_sel == b_sel);

    assign not_eq_and_not_lt = (not_equal & ~(b_lt_a | l));
    assign not_eq_and_not_gt = (not_equal & ~(b_gt_a | l));

    assign final_equ = (not_eq_and_not_lt & not_eq_and_not_gt);

    assign equal = final_equ;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    // Internal signals for gate outputs
    wire [3:0] gate_output;

    // First layer of gates (based on the diagram)
    // The diagram shows a 1-input mux-like structure feeding into multiple NAND gates
    // But since we have a 2-bit input 'in', let's interpret the circuit as implementing a decoder using NAND gates.

    // Looking at the diagram:
    // - The leftmost gate is a 1:2 multiplexer selecting between 'in[1]' and 'in[0]'? 
    //   Actually, the diagram shows a single input 'in' going to a 1:2 MUX, but that doesn't make sense for a 2-to-4 decoder.
    //   
    // Let me re-examine: The diagram has a 2-bit input 'in' (since the module header says [1:0]), 
    // and the first component is a 1:2 MUX with input 'in', select line (not shown), 
    // and outputs connected to 4 NAND gates. 
    // But wait — the MUX has two inputs labeled 1 and 0, and one output that feeds all four NAND gates.
    // That would mean all four NAND gates get the same input, which doesn't make sense for a decoder.

    // Alternative interpretation: Perhaps the "in" is actually two separate inputs, but the diagram draws them together?
    // Another possibility: The diagram might be incomplete or schematic representation.

    // Given the module header expects input [1:0] in and output [3:0] out, and it's called "decoder_2to4",
    // we should implement a standard 2-to-4 line decoder.

    // Standard 2-to-4 decoder truth table:
    // in[1:0] | out[3:0]
    // --------|--------
    //   00    |   1000
    //   01    |   0100
    //   10    |   0010
    //   11    |   0001

    // We'll use continuous assignments to implement the decoder logic.

    // Using NAND gates as per the diagram style (though we'll simplify for correctness)
    // Since the diagram is ambiguous, and the required module is a 2-to-4 decoder,
    // I'll implement the standard decoder using NAND gates.

    // For active-high outputs (standard decoder):
    // out[0] = ~(in[1] & in[0])  // but that's not right — actually:
    // out[0] should be 1 only when in==00 -> so out[0] = ~(in[1] | in[0])
    // Let's do it properly:

    out[0] = ~(in[1] | in[0]);
    out[1] = ~(~in[1] & in[0]);
    out[2] = ~(in[1] & ~in[0]);
    out[3] = ~((~in[1]) & (~in[0]));

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire a, b;
    assign a = in[1];
    assign b = in[0];

    assign out[0] = (~a) & (~b);
    assign out[1] = (~a) && b;
    assign out[2] = a & (~b);
    assign out[3] = a && b;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_in0, not_in1;
    wire nand1, nand2, nand3, nand4;

    assign not_in0 = ~in[0];
    assign not_in1 = ~in[1];

    assign nand1 = ~(in[1] & not_in0);
    assign nand2 = ~(in[1] & in[0]);
    assign nand3 = ~(in[0] & not_in1);
    assign nand4 = ~(not_in0 & not_in1);

    assign out[0] = nand1;
    assign out[1] = nand2;
    assign out[2] = nand3;
    assign out[3] = nand4;

endmodule

