module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);

always @(in) begin
    if (in[0] || in[1] || in[2] || in[3])
        case (1)
            // Priority: highest index first
            in[0]: code = 2'b00;
            in[1]: code = 2'b01;
            in[2]: code = 2'b10;
            in[3]: code = 2'b11;
            default: code = 2'b00;
        endcase
    else
        code = 2'b00;
end

endmodule

