module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state_reg;
    wire next_state_0;
    wire next_state_1;
    wire next_state_2;

    assign state = state_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= 2'b00;
        end else begin
            case (state_reg)
                2'b00: state_reg <= next_state_0;
                2'b01: state_reg <= next_state_1;
                2'b10: state_reg <= next_state_2;
                2'b11: state_reg <= 2'b00;
                default: state_reg <= 2'b00;
            endcase
        end
    end

    assign next_state_0 = ~(state_reg[1:0]);
    assign next_state_1 = state_reg[0];
    assign next_state_2 = ~(state_reg[0]);

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

    reg [1:0] present_state, next_state;

    always @(posedge clk) begin
        present_state <= next_state;
    end

    always @(*) begin
        case (present_state)
            2'b00: next_state = ~reset;
            2'b01: next_state = reset;
            2'b10: next_state = reset ^ 1;
            default: next_state = reset;
        endcase
    end

    assign state = present_state;

endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);

reg [1:0] state;
wire d0, d1;

always @(*) begin
  case (state)
    2'b00: begin
      d0 = 1'b0;
      d1 = 1'b0;
    end
    2'b01: begin
      d0 = 1'b0;
      d1 = 1'b1;
    end
    2'b10: begin
      d0 = state[0];
      d1 = 1'b0;
    end
    2'b11: begin
      d0 = 1'b1;
      d1 = 1'b0;
    end
    default: begin
      d0 = 1'b0;
      d1 = 1'b0;
    end
    $responsepriority endcase
  endcasex


always @(posedge clk) begin
  if (reset == 1'b0) begin
    state <= 2'b00;
