module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    reg [1:0] state;
    real not_item_selected;
    real item_selected_and_coins;
    real down;
    real r_reg;

    assign not_item_selected = (item_selected) ? 1.0 : 0.0;
    assign item_selected_and_coins = (item_selected & coin_inserted) ? 1.0 : 0.0;
    assign down = (state == 1 && item_selected & coin_inserted) ? 1.0 : 0.0;
    assign r_reg = (item_selected & ~down);

    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= 1'h0;
        else if (down)
            state <= 1'h0;
        else if (r_reg)
            state <= 1'h1;
        else
            state <= state;
    end

    assign state[0] = (~status & ~item_selected_and_coins | item_selected_and_coins & down | state & ~r_reg);
    assign state[1] = (~item_selected_and_coins & ~down | item_selected_and_coins & r_reg & ~down);
    assign status = (state == 1'h1);

endmodule

