    wire [0:3] q2_3;
    wire [0:3] q3_4;

    // Instantiate the least significant bit (Q0)
    gray_ff q0_inst (.clk(clk), .rst(rst), .din(q1_2[0]), .q(q0_1[0]));

    // Instantiate the second bit (Q1)
    gray_ff q1_inst (.clk(clk), .rst(rst), .din(q2_3[0]), .q(q1_2[0]));

    // Instantiate the third bit (Q2)
    gray_ff q2_inst (.clk(clk), .rst(rst), .din(q3_4[0]), .q(q2_3[0]));

    // Instantiate the most significant bit (Q3)
    gray_ff q3_inst (.clk(clk), .rst(rst), .din(~q0_1[0]), .q(q3_4[0]));

    // Construct the 4-bit Gray coded output
    assign count[7:4] = 4'b0000; // Top 4 bits are always zero
    assign count[3:0] = {q3_4, q2_3, q1_2, q0_1}; // Bottom 4 bits from feedback

    // Gray to Binary conversion for top 4 bits (always 0)
    assign count[7] = | (count[3:0]);
    assign count[6] = count[7] ^ count[1];
    assign count[5] = count[6] ^ count[2];
    assign count[4] = count[5] ^ count[3];

