  input w,
  input R,
  input E,
  input L,
  output reg Q
);

always @(posedge clk) begin
  case (w)
    1'b0: begin
      if (R == 1'b1)
        Q <= 1'b0;
      else if (E == 1'b0)
        Q <= ~Q;
    end
    1'b1: begin
      if (R == 1'b1)
        Q <= 1'b1;
      else if (E == 1'b0)
        Q <= ~Q;
    end
  endcase
end

endmodule

module TopModule (
