  input E,
  input L,
  output reg Q
);

  always @(posedge clk) begin
    if (R | (~L & S_DFFE_PP_D))
      Q <= 0;
    if (E & L)
      Q <= S_DFFE_PP_D;
    if (~E)
      Q <= 1;
  end

  assign S_DFFE_PP_D = (w | R) & (~L);

endmodule

