      equal = 1'b1;
      greaterAndGreater = 1'b1;
      disc_2 = 1'b1;
      disc = 1'b1;
      shown = 1'b1;
      err2 = 1'b1;
      eq = 1'b1;
      reset_cnt1 = 1'b1;
      reset_cnt2 = 1'b1;
      reset_cnt3 = 1'b1;
    end
    else if(reset_cnt1) begin
      greater = 1'b0;
      less = 1'b0;
      equal = 1'b0;
      greaterAndGreater = 1'b0;
      disc_2 = 1'b0;
