      eq = 1'b0;
      reset_cnt1 = 1'b0;
      reset_cnt2 = 1'b0;
      reset_cnt3 = 1'b0;
    end
    else begin
      greater = in;
      less = (~in & in);
      equal = ( greater & less );
      greaterAndGreater = ( greater & reset_cnt2 );
      disc_2 = (! greater & in);
      disc = ( (! greater & in) );
      shown = (! greater & ~reset_cnt3);
      err2 = ( shown & (! reset_cnt3 & reset_cnt2) );
      eq = ( shown & reset_cnt3);
