  input reset,
  output shift_ena
);

  // Internal signals from flip-flops
  wire S_SDFPP1; // From first DFF
  wire S_SDFPP2; // From second DFF
  wire S_SDFPP3; // From third DFF

  // D Flip-Flop: D input, C (clock), R (reset), Q output
  reg S_SDFPP1;
  reg S_SDFPP2;
  reg S_SDFPP3;

  // First DFF: D = ~S_SDFPP1 | ~reset, C = clk, R = reset
  assign S_SDFPP1 = (~S_SDFPP1) | (~reset);
  always @(posedge clk or posedge reset) begin
    if (reset)
      S_SDFPP1 <= 1'b0;
    else
      S_SDFPP1 <= S_SDFPP1; // No change on clock edge if not reset
  end

  // Second DFF: D = S_SDFPP1, C = clk, R = reset
  assign D_SDFPP2 = S_SDFPP1;
  always @(posedge clk or posedge reset) begin
    if (reset)
      S_SDFPP2 <= 1'b0;
    else
      S_SDFPP2 <= S_SDFPP1;
  end

  // Third DFF: D = S_SDFPP2, C = clk, R = reset
  assign D_SDFPP3 = S_SDFPP2;
  always @(posedge clk or posedge reset) begin
    if (reset)
      S_SDFPP3 <= 1'b0;
    else
      S_SDFPP3 <= S_SDFPP2;
  end

  // Shift enable logic
  wire or1_out = (~S_SDFPP1) & S_SDFPP2;
  wire or2_out = S_SDFPP3 | or1_out;
  assign shift_ena = or2_out;

endmodule

