  // Gate 4: NAND(a, x[0]) -> d
  // Gate 5: NAND(b, x[0]) -> e
  // Gate 6: NAND(d, c)

  assign d = ~(&2{a, x[0]});
  assign e = ~(&2{b, x[0]});
  assign f = ~(&2{d, c});

