    state_0 <= 1'b0;
    state_1 <= 1'b0;
    state_2 <= 1'b0;
    state_3 <= 1'b0;
    state_4 <= 1'b0;
    state_5 <= 1'b0;
  end else begin
    state_0 <= (state_2 & state_5) | (~state_0 & state_2);
    state_1 <= (~state_0 & ~state_2) | (state_0 & ~state_2 & ~state_5) | (~state_0 & ~state_2 & state_5);
