    output A_less     
);

    wire A_eq;
    wire A_less_sig, A_greater_sig, B_leq_sig, B_le_st;

    // Equality logic
    assign A_eq = ~(A ^ B);
    assign A_equal = A_eq;

    // Carry logic: Msb to LSB
    carry_fu build_fu(
        .carry_in(A[3], B[3]),
        .carry_out(A_greater_sig, A_less_sig, B_leq_sig)
    );

    // MSB Most Significant Bit
    MSB B[0] = ~(A[2] >= B[2]);

    // LSB logic
    OR func_fu(
        .A(A[0]),
        .B(B[0]),
        .out(A_less_sig)
    );

    // Comparison circuits
    // First comparison: A > B
    NOT func(
        .in(A > B),
        .out(A_greater)
    );

    // Second comparison: A < B
    if (A < B)
    begin
        A_less = 1'b1;
        A_greater = 1'b0;
        A_equal = 1'b0;
    end

    // Third comparison: A = B
    if (A == B)
    begin
        A_less = 1'b0;
        A_greater = 1'b0;
        A_equal = 1'b1;
    end

    // Default case
    else
    begin
        A_less = 1'b0;
        A_greater = 1'b0;
        A_equal = 1'b0;
    end

